from pysat.solvers import Cadical153, Glucose3, Minisat22
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool
import time, itertools, sys
W=6; P=36; G=9; S=4
vpool=IDPool()
def x(w,p,g): return vpool.id(('x',w,p,g))
clauses=[]
# player exactly one group
for w in range(W):
  for p in range(P):
    clauses.append([x(w,p,g) for g in range(G)])
    for g1 in range(G):
      for g2 in range(g1+1,G):
        clauses.append([-x(w,p,g1), -x(w,p,g2)])
# group exactly 4 via cardenc
for w in range(W):
  for g in range(G):
    lits=[x(w,p,g) for p in range(P)]
    enc=CardEnc.equals(lits, bound=S, vpool=vpool, encoding=EncType.seqcounter)
    clauses.extend(enc.clauses)
# week0 fixed
for p in range(P):
  clauses.append([x(0,p,p//4)])
# each later week golfer 0 group 0 wlog
for w in range(1,W): clauses.append([x(w,0,0)])
# no pair repeated: for w1<w2, g1,g2, pair p,q
cnt=0
for p in range(P):
  for q in range(p+1,P):
    for w1 in range(W):
      for w2 in range(w1+1,W):
        for g1 in range(G):
          for g2 in range(G):
            clauses.append([-x(w1,p,g1), -x(w1,q,g1), -x(w2,p,g2), -x(w2,q,g2)])
            cnt+=1
print('vars', vpool.top, 'clauses', len(clauses), 'paircls', cnt, flush=True)
t=time.time()
solver=Cadical153(bootstrap_with=clauses)
print('init', time.time()-t, flush=True)
t=time.time()
res=solver.solve()
print('res',res,'time',time.time()-t, flush=True)
if res:
 model=set(solver.get_model())
 sol=[]
 for w in range(W):
  for p in range(P):
   gs=[g for g in range(G) if x(w,p,g) in model]
   if len(gs)!=1: print('bad',w,p,gs); sys.exit()
   sol.append(gs[0])
 print(sol)
 # verify
 ok=True
 for w in range(W):
  counts=[0]*G
  for p in range(P): counts[sol[w*P+p]]+=1
  if counts != [4]*G: print('counts',w,counts); ok=False
 seen={}
 for w in range(W):
  for p in range(P):
   for q in range(p+1,P):
    if sol[w*P+p]==sol[w*P+q]:
     if (p,q) in seen: print('repeat',p,q,seen[(p,q)],w); ok=False; raise SystemExit
     seen[(p,q)]=w
 print('ok',ok,'pairs',len(seen))
